8	declare_rule! {
9	    /// Disallow Array constructors.
10	    ///
11	    /// Use of the Array constructor to construct a new array is generally discouraged in favor of array literal notation because of the single-argument pitfall and because the Array global may be redefined.
12	    /// The exception is when the Array constructor intentionally creates sparse arrays of a specified size by giving the constructor a single numeric argument.
13	    ///
14	    /// ## Examples
15	    ///
16	    /// ### Invalid
17	    ///
18	    /// ```js,expect_diagnostic
19	    /// Array();
20	    /// ```
21	    ///
22	    /// ```js,expect_diagnostic
23	    /// Array(0, 1, 2);
24	    /// ```
25	    ///
26	    /// ```js,expect_diagnostic
27	    /// new Array(0, 1, 2);
28	    /// ```
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// Array(...args);
32	    /// ```
33	    ///
34	    /// ### Valid
35	    ///
36	    /// ```js
37	    /// Array(500);
38	    /// ```
39	    ///
40	    /// ```js
41	    /// [0, 1, 2];
42	    /// ```
43	    ///
44	    pub UseArrayLiterals {
45	        version: "1.7.2",
46	        name: "useArrayLiterals",
47	        sources: &[RuleSource::Eslint("no-array-constructor")],
48	        recommended: false,
49	        fix_kind: FixKind::Unsafe,
50	    }
51	}
52	
53	impl Rule for UseArrayLiterals {
54	    type Query = Ast<JsExpressionStatement>;
55	    type State = ();
56	    type Signals = Option<Self::State>;
57	    type Options = ();
58	
59	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
60	        let expression_statement = ctx.query();
61	
62	        let expression = expression_statement.expression().ok()?;
63	
64	        match expression {
65	            AnyJsExpression::JsCallExpression(call_expression) => {
66	                let callee = call_expression.callee().ok()?;
67	                let arguments = call_expression.arguments().ok()?;
68	                validate(&callee, &arguments)
69	            }
70	            AnyJsExpression::JsNewExpression(new_expression) => {
71	                let callee = new_expression.callee().ok()?;
72	                let arguments = new_expression.arguments()?;
73	                validate(&callee, &arguments)
74	            }
75	            _ => None,
76	        }
77	    }
78	
79	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
80	        let node = ctx.query();
81	        Some(
82	            RuleDiagnostic::new(
83	                rule_category!(),
84	                node.range(),
85	                markup! {
86	                    "Don't use Array constructors."
87	                },
88	            )
89	            .note(markup! {
90	                "Use of the Array constructor is not allowed except creating sparse arrays of a specified size by giving a single numeric argument."
91	            })
92	            .note(markup! {
93	                "The array literal notation [] is preferable."
94	            }),
95	        )
96	    }
97	}
98	
99	fn validate(callee: &AnyJsExpression, arguments: &JsCallArguments) -> Option<()> {
100	    if callee.text() != "Array" {
101	        return None;
102	    }
103	    let mut args_iter = arguments.args().into_iter();
104	    let first_arg = args_iter.next();
105	    let second_arg = args_iter.next();
106	    if first_arg.is_some()
107	        && second_arg.is_none()
108	        && !matches!(first_arg?.ok()?, AnyJsCallArgument::JsSpread(_))
109	    {
110	        return None;
111	    }
112	    Some(())
113	}
