100	    parser_options: JsParserOptions,
101	) -> usize {
102	    let parsed = parse(input_code, source_type, parser_options.clone());
103	    let root = parsed.tree();
104	
105	    let mut diagnostics = Vec::new();
106	    let mut code_fixes = Vec::new();
107	    let options = create_analyzer_options(input_file, &mut diagnostics);
108	    let manifest = load_manifest(input_file, &mut diagnostics);
109	
110	    let (_, errors) =
111	        biome_js_analyze::analyze(&root, filter, &options, source_type, manifest, |event| {
112	            if let Some(mut diag) = event.diagnostic() {
113	                for action in event.actions() {
114	                    if check_action_type.is_suppression() {
115	                        if action.is_suppression() {
116	                            check_code_action(
117	                                input_file,
118	                                input_code,
119	                                source_type,
120	                                &action,
121	                                parser_options.clone(),
122	                            );
123	                            diag = diag.add_code_suggestion(CodeSuggestionAdvice::from(action));
124	                        }
125	                    } else if !action.is_suppression() {
126	                        check_code_action(
127	                            input_file,
128	                            input_code,
129	                            source_type,
130	                            &action,
131	                            parser_options.clone(),
132	                        );
133	                        diag = diag.add_code_suggestion(CodeSuggestionAdvice::from(action));
134	                    }
135	                }
136	
137	                let error = diag.with_severity(Severity::Warning);
138	                diagnostics.push(diagnostic_to_string(file_name, input_code, error));
139	                return ControlFlow::Continue(());
140	            }
141	
142	            for action in event.actions() {
143	                if check_action_type.is_suppression() {
144	                    if action.category.matches("quickfix.suppressRule") {
145	                        check_code_action(
146	                            input_file,
147	                            input_code,
148	                            source_type,
149	                            &action,
150	                            parser_options.clone(),
151	                        );
152	                        code_fixes.push(code_fix_to_string(input_code, action));
153	                    }
154	                } else if !action.category.matches("quickfix.suppressRule") {
155	                    check_code_action(
156	                        input_file,
157	                        input_code,
158	                        source_type,
159	                        &action,
160	                        parser_options.clone(),
161	                    );
162	                    code_fixes.push(code_fix_to_string(input_code, action));
163	                }
164	            }
165	
166	            ControlFlow::<Never>::Continue(())
167	        });
