171	    }
172	
173	    write_analyzer_snapshot(
174	        snapshot,
175	        input_code,
176	        diagnostics.as_slice(),
177	        code_fixes.as_slice(),
178	        source_type.file_extension(),
179	    );
180	
181	    diagnostics.len()
182	}
